    boolean directory(String id)throws Exception{return node(id).getString("mime").equals(Document.MIME_TYPE_DIR);}
    void parent(String id)throws Exception{if(!directory(id))throw new FileNotFoundException("Not a directory");}
    boolean contains(JSONArray a,String value)throws Exception{for(int i=0;i<a.length();i++)if(a.getString(i).equals(value))return true;return false;}
