    MatrixCursor cursor(String[] projection){return new MatrixCursor(projection==null?DOC_COLUMNS:projection);}
    void row(MatrixCursor cursor,String id)throws Exception{JSONObject n=node(id);MatrixCursor.RowBuilder row=cursor.newRow();for(String key:cursor.getColumnNames()){Object value=null;if(key.equals(Document.COLUMN_DOCUMENT_ID))value=id;else if(key.equals(Document.COLUMN_DISPLAY_NAME))value=n.getString("name");else if(key.equals(Document.COLUMN_MIME_TYPE))value=n.getString("mime");else if(key.equals(Document.COLUMN_FLAGS))value=flags(id);else if(key.equals(Document.COLUMN_SIZE)&&!directory(id)&&!n.optBoolean("virtual"))value=data(id).length();else if(key.equals(Document.COLUMN_LAST_MODIFIED))value=n.getLong("modified");row.add(value);}}
    @Override public synchronized Cursor queryRoots(String[] projection)throws FileNotFoundException{try{MatrixCursor c=new MatrixCursor(projection==null?ROOT_COLUMNS:projection);if(!active().isEmpty()){MatrixCursor.RowBuilder row=c.newRow();for(String key:c.getColumnNames()){Object v=null;if(key.equals(Root.COLUMN_ROOT_ID))v="fixture";else if(key.equals(Root.COLUMN_DOCUMENT_ID))v=active()+".root";else if(key.equals(Root.COLUMN_TITLE))v=TITLE;else if(key.equals(Root.COLUMN_FLAGS))v=Root.FLAG_SUPPORTS_CREATE|Root.FLAG_SUPPORTS_IS_CHILD;else if(key.equals(Root.COLUMN_MIME_TYPES))v="*/*";else if(key.equals(Root.COLUMN_ICON))v=android.R.drawable.ic_menu_agenda;row.add(v);}}return c;}catch(Exception e){throw failure(e);}}
    @Override public synchronized Cursor queryDocument(String id,String[] projection)throws FileNotFoundException{try{binderEntry("query",id);MatrixCursor c=cursor(projection);row(c,id);return c;}catch(Exception e){throw failure(e);}}
    @Override public synchronized Cursor queryChildDocuments(String id,String[] projection,String sort)throws FileNotFoundException{try{binderEntry("children",id);MatrixCursor c=cursor(projection);for(String child:children(id))row(c,child);return c;}catch(Exception e){throw failure(e);}}
    @Override public synchronized boolean isChildDocument(String parent,String id){try{return descendant(parent,id);}catch(Exception e){return false;}}
    @Override public synchronized String createDocument(String parent,String mime,String name)throws FileNotFoundException{try{binderEntry("create",parent);if(name.isEmpty()||name.contains("/")||name.contains("\\"))throw new IOException("Bad fixture name");String id=add(parent,name,mime,directoryMime(mime)?null:new byte[0]);event("create",id,parent);binderBoundary("create","committed",parent);return id;}catch(Exception e){throw failure(e);}}
    static boolean directoryMime(String mime){return mime.equals(Document.MIME_TYPE_DIR);}
    @Override public synchronized String renameDocument(String id,String name)throws FileNotFoundException{try{binderEntry("rename",id);editable(id);node(id).put("name",name);event("rename",id,name);binderBoundary("rename","committed",id);return id;}catch(Exception e){throw failure(e);}}
    String cloneTo(String source,String target)throws Exception{JSONObject n=node(source);String id=add(target,n.getString("name"),n.getString("mime"),directory(source)?null:Files.readAllBytes(data(source).toPath()));if(n.optBoolean("virtual"))node(id).put("virtual",true);if(directory(source))for(String child:children(source))cloneTo(child,id);return id;}
